-- True DB source definitions (frozen from current Supabase metadata); no data/secrets.
-- Isolated PG17 fixture. No contact with official database.
CREATE SCHEMA IF NOT EXISTS lf_ops;
CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE TABLE lf_ops.pantallas (
 "id" integer GENERATED BY DEFAULT AS IDENTITY,
 "codigo" text,
 "nombre" text,
 "descripcion" text,
 "flujo" text,
 "paso" text,
 "estado" text,
 "activa" boolean DEFAULT false,
 "created_at" timestamptz DEFAULT now(),
 "drive_file_id" text,
 "drive_url" text,
 "drive_filename" text,
 "drive_updated_at" timestamptz,
 "module_code" text,
 "version" text,
 "owner_name" text,
 "objective" text,
 "allowed_profiles" jsonb,
 "dependencies" jsonb,
 "source_decision_id" text,
 "updated_at" timestamptz DEFAULT now(),
 "module_id" bigint,
 "source_decision_number" bigint
);
CREATE TABLE lf_ops.reglas (
 "id" integer GENERATED BY DEFAULT AS IDENTITY,
 "codigo" text,
 "categoria" text,
 "titulo" text,
 "descripcion" text,
