CREATE UNIQUE INDEX lf_reglas_code_uniq_fixture_v1 ON lf_ops.reglas(codigo);
CREATE UNIQUE INDEX lf_step_run_order_uniq_fixture_v1 ON public.lf_operation_execution_steps(execution_id,step_order);
